-- ---------------------------------------------------
-- Schema Definition SQL
-- ---------------------------------------------------

CREATE TABLE properties (
	property_id VARCHAR(64) NOT NULL, 
	title VARCHAR(255), 
	prop_address VARCHAR(255), 
	postal_code VARCHAR(255), 
	department VARCHAR(255), 
	city VARCHAR(255), 
	max_guests INTEGER, 
	cleaning_fee FLOAT, 
	base_price FLOAT, 
	prop_type VARCHAR(255), 
	surface INTEGER, 
	PRIMARY KEY (property_id)
);

CREATE TABLE guests (
	guest_id VARCHAR(64) NOT NULL, 
	first_name VARCHAR(255), 
	last_name VARCHAR(255), 
	email VARCHAR(255), 
	phone VARCHAR(255), 
	guest_lang VARCHAR(255), 
	locale VARCHAR(255), 
	guest_geo VARCHAR(255), 
	PRIMARY KEY (guest_id)
);

CREATE TABLE teams (
	team_id VARCHAR(64) NOT NULL, 
	team_group VARCHAR(255), 
	team_role VARCHAR(255), 
	first_name VARCHAR(255), 
	last_name VARCHAR(255), 
	gender VARCHAR(255), 
	sector VARCHAR(255), 
	languages TEXT, 
	managed_by VARCHAR(255), 
	PRIMARY KEY (team_id)
);

CREATE TABLE bookings (
	booking_id VARCHAR(64) NOT NULL, 
	guest_id VARCHAR(64), 
	property_id VARCHAR(64), 
	check_in VARCHAR(255), 
	check_out VARCHAR(255), 
	nights INTEGER, 
	total_price FLOAT, 
	book_status VARCHAR(255), 
	source VARCHAR(255), 
	assigned_to VARCHAR(255), 
	PRIMARY KEY (booking_id), 
	FOREIGN KEY(guest_id) REFERENCES guests (guest_id), 
	FOREIGN KEY(property_id) REFERENCES properties (property_id)
);

CREATE TABLE tasks (
	task_id VARCHAR(64) NOT NULL, 
	property_id VARCHAR(64), 
	booking_id VARCHAR(64), 
	category VARCHAR(255), 
	title VARCHAR(255), 
	task_date VARCHAR(255), 
	task_status VARCHAR(255), 
	assigned_by VARCHAR(255), 
	assigned_to VARCHAR(255), 
	parent_task_id VARCHAR(64), 
	PRIMARY KEY (task_id), 
	FOREIGN KEY(property_id) REFERENCES properties (property_id), 
	FOREIGN KEY(booking_id) REFERENCES bookings (booking_id)
);

